SELECT n.nspname AS schema_name, p.proname AS routine_name, oidvectortypes(p.proargtypes) AS arguments, format_type(p.prorettype, NULL) AS return_type, p.provolatile AS volatility, p.prosecdef AS security_definer, l.lanname AS language, u.usename AS owner FROM pg_proc p JOIN pg_namespace n ON p.pronamespace = n.oid JOIN pg_language l ON p.prolang = l.oid LEFT JOIN pg_user u ON p.proowner = u.usesysid WHERE n.nspname = :schema AND p.proname = :name AND p.pronargs = 0;
